async function seedLocations() {
  try {
    console.log(`Starting to seed ${locations.length} locations for starflake schema...`);
    let successCount = 0;
    let errorCount = 0;

    for (const location of locations) {
      try {
        console.log(`Seeding location ${location.desa}...`);

        await db.query(
          `INSERT INTO forecasting.dim_location
          (location_id, subdistrict_name, district_name, city_name, province_name, latitude, longitude, timezone)
          VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
          ON CONFLICT (location_id) DO NOTHING`,
          [
            location.adm4,
            location.desa,
            location.kecamatan,
            location.kotkab,
            location.provinsi,
            location.lat,
            location.lon,
            location.timezone,
          ]
        );

        console.log(`Location ${location.desa} seeded successfully!`);
        successCount++;
      } catch (error) {
        console.error(`Error seeding location ${location.desa}:`, error);
        errorCount++;
      }
    }

    console.log("\nLocation Seeder execution summary:");
    console.log(`Total locations: ${locations.length}`);
    console.log(`Successfully seeded: ${successCount}`);
    console.log(`Failed: ${errorCount}`);

    if (errorCount > 0) {
      throw new Error(`Failed to seed ${errorCount} locations`);
    }
  } catch (error) {
    console.error("Error in seedLocations:", error);
    throw error;
  }
}

module.exports = seedLocations;
